begin;
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.denies(command text,expected text,label text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected% got% %',label,expected,sqlstate,sqlerrm;end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % accepted',label;end$$;
create temp table smart_test(k text primary key,v jsonb);grant all on smart_test to authenticated;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
insert into smart_test values('segment',public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','{"action":"create_segment","name":"Organization","description":"Synthetic"}'));
insert into smart_test select 'group',public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000002',jsonb_build_object('action','create_group','segmentId',v->>'segmentId','name','Cooks','description','','rules','[{"field":"title","values":["Cook"]},{"field":"team","values":["North"]},{"field":"custom:branch","values":["New York"]}]'::jsonb))from smart_test where k='segment';
insert into smart_test select 'members',public.read_smart_groups('88000000-0000-4000-8000-000000000001','members',(v->>'groupId')::uuid,null,'all')from smart_test where k='group';
reset role;
insert into smart_test select 'readMarks',jsonb_build_array((select md5(string_agg(to_jsonb(a)::text,'|'order by id))from public.smart_group_audit a),(select md5(string_agg(to_jsonb(o)::text,'|'order by operation_id))from workforce_private.smart_group_operations o));
set role authenticated;
select public.read_smart_groups('88000000-0000-4000-8000-000000000001','groups');
select public.read_smart_groups('88000000-0000-4000-8000-000000000001','segments');
select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook"]}]');
select public.read_smart_groups_access('88000000-0000-4000-8000-000000000001');
reset role;
select pg_temp.check(v=jsonb_build_array((select md5(string_agg(to_jsonb(a)::text,'|'order by id))from public.smart_group_audit a),(select md5(string_agg(to_jsonb(o)::text,'|'order by operation_id))from workforce_private.smart_group_operations o)),'catalog members preview and access reads do not write audits or receipts')from smart_test where k='readMarks';
set role authenticated;
select pg_temp.check(v#>>'{counts,records}'='1005','exact full population beyond1000 excludes archived')from smart_test where k='members';
select pg_temp.check(v#>>'{counts,unlinked}'='992'and v#>>'{counts,eligible}'='10'and v#>>'{counts,unavailable}'='3','unlinked confirmed active suspended unconfirmed anonymous partition')from smart_test where k='members';
select pg_temp.check(jsonb_array_length(v->'members')=50 and v->'nextCursor'<>'null','member page bounded with scoped cursor')from smart_test where k='members';
select pg_temp.check((public.read_smart_groups('88000000-0000-4000-8000-000000000001','members',(v#>>'{group,id}')::uuid,null,'all','',50,v->'nextCursor')#>>'{members,0,id}')<>v#>>'{members,0,id}','second page advances beyond first50')from smart_test where k='members';
select pg_temp.denies(format('select public.read_smart_groups(%L,%L,%L,null,%L,%L,50,%L::jsonb)','88000000-0000-4000-8000-000000000001','members',v#>>'{group,id}','all','new search',v->'nextCursor'),'40001','changed search refuses previous cursor')from smart_test where k='members';
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["cook"]}]')#>>'{counts,records}'='0','case-sensitive exact matching');
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["cook","Cook"]},{"field":"team","values":["North"]}]')#>>'{counts,records}'='1005','OR within clause and AND across clauses');
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook "]}]')#>>'{counts,records}'='0','literal alternatives retain trailing spaces');
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Co"]}]')#>>'{counts,records}'='0','no partial or regex matching');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[]')$q$,'22023','zero-rule broadcast rejected');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"custom:missing","values":["x"]}]')$q$,'22023','unknown preview fields rejected');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook","Cook"]}]')$q$,'22023','duplicate literal alternatives rejected');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":null,"values":["x"]}]')$q$,'22023','null rule field never broadens');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title"}]')$q$,'22023','missing values never broadens');
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["\t"]}]')$q$,'22023','tab-only alternatives rejected');
do $$declare cp integer;begin
 foreach cp in array array[11,12,13,160,65279]loop
  perform pg_temp.denies(format('select public.read_smart_groups(%L,%L,null,null,%L,%L,50,null,%L::jsonb)','88000000-0000-4000-8000-000000000001','preview','all','',jsonb_build_array(jsonb_build_object('field','title','values',jsonb_build_array(chr(cp))))),'22023','direct SQL whitespace-only CHR'||cp||' rejected');
 end loop;
end$$;
select pg_temp.denies(format('select public.read_smart_groups(%L,%L,null,null,%L,%L,50,null,%L::jsonb)','88000000-0000-4000-8000-000000000001','preview','all','',jsonb_build_array(jsonb_build_object('field','title','values',jsonb_build_array(repeat('😀',251))))),'22023','direct signed rules enforce UTF16 bound');
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,jsonb_build_array(jsonb_build_object('field','title','values',jsonb_build_array(repeat('😀',250)))))#>>'{counts,records}'='0','UTF16 boundary accepted without truncation');
select pg_temp.check(public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','{"action":"create_segment","name":"Organization","description":"Synthetic"}')=(select v from smart_test where k='segment'),'same UUID returns original receipt');
select pg_temp.denies($q$select public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','{"action":"create_segment","name":"Changed","description":"Synthetic"}')$q$,'40001','UUID payload mismatch denied');
select pg_temp.denies(format('select public.save_smart_group(%L,gen_random_uuid(),%L::jsonb)','88000000-0000-4000-8000-000000000001',jsonb_build_object('action','archive_segment','segmentId',v->>'segmentId','revision',1)),'40001','segment archive blocks active children')from smart_test where k='segment';
select pg_temp.denies(format('select public.save_smart_group(%L,gen_random_uuid(),%L::jsonb)','88000000-0000-4000-8000-000000000001',jsonb_build_object('action','edit_group','groupId',v->>'groupId','segmentId',v->>'segmentId','revision',9,'name','Cooks','description','','rules','[{"field":"title","values":["Cook"]}]'::jsonb)),'40001','stale revision cannot edit')from smart_test where k='group';
do $$declare first jsonb;second jsonb;third jsonb;begin
 perform public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"action":"create_segment","name":"İ","description":""}');
 perform public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"action":"create_segment","name":"I","description":""}');
 first:=public.read_smart_groups('88000000-0000-4000-8000-000000000001','segments',null,null,'all','',1);
 second:=public.read_smart_groups('88000000-0000-4000-8000-000000000001','segments',null,null,'all','',1,first->'nextCursor');
 third:=public.read_smart_groups('88000000-0000-4000-8000-000000000001','segments',null,null,'all','',1,second->'nextCursor');
 perform pg_temp.check(first#>>'{segments,0,id}'<>second#>>'{segments,0,id}'and second#>>'{segments,0,id}'<>third#>>'{segments,0,id}'and third->'nextCursor'='null'::jsonb,'SQL name positions support Turkish folded ties without skipped or repeated rows');
 perform public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"action":"create_segment","name":"Literal %_\\","description":""}');
 perform pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','segments',null,null,'all','%_'||chr(92),50)#>>'{counts,total}'='1','literal percent underscore backslash search');
end$$;
reset role;
-- Every legacy change below is restored by this enclosing rollback.
update public.agents set title=''where id='77000000-0000-4000-8000-000000000001';
set role authenticated;
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook"]}]')#>>'{counts,records}'='1004','fresh profile changes immediately change membership missing values fail');
select pg_temp.denies(format('select public.read_smart_groups(%L,%L,%L,null,%L,%L,50,%L::jsonb)','88000000-0000-4000-8000-000000000001','members',v#>>'{group,id}','all','',v->'nextCursor'),'40001','profile changes invalidate population cursor')from smart_test where k='members';
reset role;update public.agents set title='Cook'where id='77000000-0000-4000-8000-000000000001';
update public.tenant_memberships set status='suspended'where user_id='00000000-0000-4000-8001-000000000002';
set role authenticated;
select pg_temp.denies(format('select public.read_smart_groups(%L,%L,%L,null,%L,%L,50,%L::jsonb)','88000000-0000-4000-8000-000000000001','members',v#>>'{group,id}','all','',v->'nextCursor'),'40001','eligibility changes invalidate population cursor')from smart_test where k='members';
reset role;update public.tenant_memberships set status='active'where user_id='00000000-0000-4000-8001-000000000002';
update public.agents set user_id='00000000-0000-4000-8001-000000000015'where id='77000000-0000-4000-8000-000000000013';
set role authenticated;
select pg_temp.check(public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook"]}]')#>>'{counts,records}'='1005'and public.read_smart_groups('88000000-0000-4000-8000-000000000001','preview',null,null,'all','',50,null,'[{"field":"title","values":["Cook"]}]')#>>'{counts,eligible}'='11','Auth relink retains Agent organizational identity and reevaluates eligibility');
select pg_temp.check((select count(*)from public.updates_recipients where actor_id='00000000-0000-4000-8001-000000000014')=1,'organizational relink does not transfer fixed communication audience');
select pg_temp.denies(format('select public.read_smart_groups(%L,%L,%L,null,%L,%L,50,%L::jsonb)','88000000-0000-4000-8000-000000000001','members',v#>>'{group,id}','all','',v->'nextCursor'),'40001','Auth relink invalidates old membership cursor')from smart_test where k='members';
reset role;update public.agents set user_id='00000000-0000-4000-8001-000000000014'where id='77000000-0000-4000-8000-000000000013';
delete from public.agent_fields where tenant_id='88000000-0000-4000-8000-000000000001'and key='branch';
set role authenticated;
select pg_temp.check((r#>>'{group,needsReview}')::boolean and r->'counts'='null'::jsonb and r->'matchedCount'='null'::jsonb and r->'members'='[]'::jsonb and r#>>'{group,invalidFields,0}'='custom:branch','removed field yields explicit review and null population')from(select public.read_smart_groups('88000000-0000-4000-8000-000000000001','members',(v->>'groupId')::uuid,null,'all')r from smart_test where k='group')q;
select pg_temp.check((public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','archive_group','groupId',v->>'groupId','revision',1))->>'revision')='2','invalid group can be archived')from smart_test where k='group';
select pg_temp.denies(format('select public.save_smart_group(%L,gen_random_uuid(),%L::jsonb)','88000000-0000-4000-8000-000000000001',jsonb_build_object('action','restore_group','groupId',v->>'groupId','revision',2)),'22023','invalid archived group cannot restore')from smart_test where k='group';
select pg_temp.check((public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','edit_group','groupId',v->>'groupId','segmentId',v->>'segmentId','revision',2,'name','Repaired','description','','rules','[{"field":"title","values":["Cook"]}]'::jsonb))->>'revision')='3','archived group can repair under active parent')from smart_test where k='group';
select public.save_smart_group('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','archive_segment','segmentId',v->>'segmentId','revision',1))from smart_test where k='segment';
select pg_temp.denies(format('select public.save_smart_group(%L,gen_random_uuid(),%L::jsonb)','88000000-0000-4000-8000-000000000001',jsonb_build_object('action','restore_group','groupId',v->>'groupId','revision',3)),'40001','restore requires active parent')from smart_test where k='group';
select pg_temp.check(public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000002',jsonb_build_object('action','create_group','segmentId',v->>'segmentId','name','Cooks','description','','rules','[{"field":"title","values":["Cook"]},{"field":"team","values":["North"]},{"field":"custom:branch","values":["New York"]}]'::jsonb))=(select v from smart_test where k='group'),'management replay returns original acknowledgement after lifecycle or field changes')from smart_test where k='segment';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000903',false);
