select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001')$q$,'42501','manager module read denied');
select pg_temp.denies($q$select * from workforce_private.smart_group_eligibility('88000000-0000-4000-8000-000000000001')$q$,'42501','eligibility helper cannot expose to manager');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000904',false);
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001')$q$,'42501','employee module denied');
select pg_temp.denies($q$insert into public.smart_group_segments(tenant_id,name,description)values('88000000-0000-4000-8000-000000000001','Direct','')$q$,'42501','direct signed writes denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000902',false);
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000002')$q$,'42501','foreign tenant unavailable even to local admin');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
