reset role;update auth.users set email_confirmed_at=now(),is_anonymous=true where id='00000000-0000-4000-8000-000000000901';set role authenticated;
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001')$q$,'42501','anonymous current actor denied');
reset role;update auth.users set is_anonymous=false where id='00000000-0000-4000-8000-000000000901';update public.tenant_memberships set status='suspended'where tenant_id='88000000-0000-4000-8000-000000000001'and user_id='00000000-0000-4000-8000-000000000901';set role authenticated;
select pg_temp.denies($q$select public.read_smart_groups('88000000-0000-4000-8000-000000000001')$q$,'42501','suspended current membership denied');
