select pg_temp.denies($q$select public.save_smart_group('88000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','{"action":"create_segment","name":"Organization","description":"Synthetic"}')$q$,'42501','current revoked management authority checked before receipt');
reset role;
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('read_smart_groups','read_smart_groups_access','save_smart_group')and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE')or p.prosecdef or p.proconfig is distinct from array['search_path=""'])),'new public RPCs invoker empty path authenticated-only');
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='workforce_private'and(p.proname like 'smart_group_%'or p.proname='save_smart_group')and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'private helpers neutralize all default EXECUTE grants');
rollback;
